def maximum_complete_index_sum(nums):
    groups={}
    for index,value in enumerate(nums,1):
        key=index;factor=2
        while factor*factor<=key:
            while key%(factor*factor)==0:key//=factor*factor
            factor+=1
        groups[key]=groups.get(key,0)+value
    return max(groups.values())

